<?php declare(strict_types=1);require_once __DIR__.'/_common.php';if(post()){verifyCsrf();$id=(int)$_POST['id'];$status=$_POST['status']??'';if(in_array($status,['verified','rejected'],true)){db()->prepare('UPDATE participation_claims SET status=?,verified_by=?,verified_at=NOW() WHERE id=?')->execute([$status,$admin['id'],$id]);adminAudit('participation_'.$status,'participation_claim',$id);flash('success','Participation claim updated.');}redirect('participation.php');}$claims=db()->query("SELECT c.*,u.full_name,e.title_en,e.event_date FROM participation_claims c JOIN users u ON u.id=c.member_id JOIN events e ON e.id=c.event_id ORDER BY FIELD(c.status,'pending','verified','rejected'),c.created_at DESC")->fetchAll();$pageTitle='Participation claims';require dirname(__DIR__).'/includes/header.php';?><section class="section"><div class="container"><p class="eyebrow">Member activity verification</p><h1 class="section-title">Participation claims.</h1><div class="table-wrap" style="margin-top:30px"><table><thead><tr><th>Member</th><th>Event</th><th>Claimed date</th><th>Details</th><th>Action</th></tr></thead><tbody><?php foreach($claims as $c):?><tr><td><?=e($c['full_name'])?></td><td><?=e($c['title_en'])?></td><td><?=e($c['participation_date'])?></td><td style="white-space:normal"><?=e($c['details'])?></td><td><?php if($c['status']==='pending'):?><form method="post" class="admin-actions"><?=csrfField()?><input type="hidden" name="id" value="<?=$c['id']?>"><button class="btn primary" name="status" value="verified">Verify</button><button class="btn coral" name="status" value="rejected">Reject</button></form><?php else:?><span><?=e($c['status'])?></span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></section><?php require dirname(__DIR__).'/includes/footer.php';
